import{uid as t}from"../sidebar/ui/Dom.js";import{TextStats as s}from"../analysis/TextStats.js";export class SnapshotService{constructor(t,s){this.store=t,this.settings=s}key(t){return`snapshots:${t}`}async list(t){return await this.store.get(this.key(t),[])||[]}async capture(e,i,r="manual"){if(!i||!i.trim())return null;const n=await this.list(e);if(n[0]?.text===i)return n[0];const a={id:t("snap"),at:(new Date).toISOString(),label:r,words:s.words(i),text:i};n.unshift(a);const o=this.settings.num("editor.maksSnapshot");return await this.store.set(this.key(e),n.slice(0,o)),a}async restore(t,s){return(await this.list(t)).find(t=>t.id===s)||null}async remove(t,s){const e=await this.list(t),i=e.filter(t=>t.id!==s);return await this.store.set(this.key(t),i),e.length-i.length}async clear(t){await this.store.remove(this.key(t))}static diff(t,s,e=60){const i=String(t||"").split(/\s+/).filter(Boolean),r=String(s||"").split(/\s+/).filter(Boolean),n=[];let a=0,o=0;for(;(a<i.length||o<r.length)&&n.length<e;){if(i[a]===r[o]){a++,o++;continue}const t=r.indexOf(i[a],o),s=i.indexOf(r[o],a);if(t>-1&&(-1===s||t-o<=s-a))for(;o<t&&n.length<e;)n.push({t:"+",w:r[o++]});else if(s>-1)for(;a<s&&n.length<e;)n.push({t:"-",w:i[a++]});else a<i.length&&n.push({t:"-",w:i[a++]}),o<r.length&&n.push({t:"+",w:r[o++]})}return n}static summarizeDiff(t,e){const i=s.words(t),r=s.words(e);return{before:i,after:r,delta:r-i}}}